/**
 * Every pair this instance has admitted, withdrawn ones included: an approval
 * that vanished from the list would read as one nobody ever made.
 */
export const listApprovals = <ThrowOnError extends boolean = false>(options?: Options<ListApprovalsData, ThrowOnError>): RequestResult<ListApprovalsResponses, ListApprovalsErrors, ThrowOnError> => (options?.client ?? client).get<ListApprovalsResponses, ListApprovalsErrors, ThrowOnError>({ url: '/api/v1/evaluation-approvals', ...options });

/**
 * Admit one pinned pair.
 *
 * The operator act that authorises publication, separated from publishing so
 * that every later repetition — from a worker, a schedule or CI — needs
 * nothing on the server's host. `Admin`, not `Editor`: an ingest token is an
 * editor by construction, and a producer that can admit its own evidence is
 * not an approval. Idempotent for the pair; a bundle that changed underneath
 * an admitted pair conflicts rather than moving what earlier results mean.
 */
export const approveSource = <ThrowOnError extends boolean = false>(options: Options<ApproveSourceData, ThrowOnError>): RequestResult<ApproveSourceResponses, ApproveSourceErrors, ThrowOnError> => (options.client ?? client).post<ApproveSourceResponses, ApproveSourceErrors, ThrowOnError>({
    url: '/api/v1/evaluation-approvals',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * The address one declaration's bundle is staged under, and the pair it names.
 *
 * A caller cannot work this out: it is a digest over the canonicalised
 * declaration, and a second implementation of that in another language is a
 * second answer to what a pair *is*. Pure — it reads no store and admits
 * nothing — so it is the one route here below `admin`, and a declaration it
 * refuses is a 400 saying what is wrong with it rather than a digest of
 * something invalid.
 */
export const addressApproval = <ThrowOnError extends boolean = false>(options: Options<AddressApprovalData, ThrowOnError>): RequestResult<AddressApprovalResponses, AddressApprovalErrors, ThrowOnError> => (options.client ?? client).post<AddressApprovalResponses, AddressApprovalErrors, ThrowOnError>({
    url: '/api/v1/evaluation-approvals/address',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Withdraw one. Every result measured under that pair stops being readable and
 * no new one can be published; nothing already published has its retention
 * moved, in either direction. Final for this approval ID.
 */
export const withdrawApproval = <ThrowOnError extends boolean = false>(options: Options<WithdrawApprovalData, ThrowOnError>): RequestResult<WithdrawApprovalResponses, WithdrawApprovalErrors, ThrowOnError> => (options.client ?? client).delete<WithdrawApprovalResponses, WithdrawApprovalErrors, ThrowOnError>({ url: '/api/v1/evaluation-approvals/{approval_id}', ...options });

/**
 * Remove every staged member of one pair.
 *
 * What it does not do is un-admit anything: an approval is withdrawn through
 * its own route, and evidence already published under this pair keeps reading
 * until the adapter is asked for bytes that are no longer there. Use it to
 * correct a bundle before approving, or to clear one that was withdrawn.
 */
export const discardBundle = <ThrowOnError extends boolean = false>(options: Options<DiscardBundleData, ThrowOnError>): RequestResult<DiscardBundleResponses, DiscardBundleErrors, ThrowOnError> => (options.client ?? client).delete<DiscardBundleResponses, DiscardBundleErrors, ThrowOnError>({ url: '/api/v1/evaluation-approvals/{approval_id}/bundle', ...options });

/**
 * What is staged for one pair. Names and sizes: the digests are the
 * declaration's, and a second copy of them here could only disagree.
 */
export const listBundle = <ThrowOnError extends boolean = false>(options: Options<ListBundleData, ThrowOnError>): RequestResult<ListBundleResponses, ListBundleErrors, ThrowOnError> => (options.client ?? client).get<ListBundleResponses, ListBundleErrors, ThrowOnError>({ url: '/api/v1/evaluation-approvals/{approval_id}/bundle', ...options });

/**
 * Stage one member of a bundle, by the name the declaration gives it.
 *
 * This is what lets a *new* pair be admitted with nobody on the server's
 * host. Admin, because approving is: an ingest token is an editor by
 * construction, and bytes that decide what may be published are the operator's
 * act rather than the producer's.
 *
 * It admits nothing on its own. The approval that follows resolves the whole
 * bundle and records its digest, so bytes staged after one do not widen it —
 * they stop that pair reading until they are what was admitted again.
 */
export const stageBundle = <ThrowOnError extends boolean = false>(options: Options<StageBundleData, ThrowOnError>): RequestResult<StageBundleResponses, StageBundleErrors, ThrowOnError> => (options.client ?? client).put<StageBundleResponses, StageBundleErrors, ThrowOnError>({
    bodySerializer: null,
    url: '/api/v1/evaluation-approvals/{approval_id}/bundle/{name}',
    ...options,
    headers: {
        'Content-Type': 'application/octet-stream',
        ...options.headers
    }
});

