export const forgetResult = <ThrowOnError extends boolean = false>(options: Options<ForgetResultData, ThrowOnError>): RequestResult<ForgetResultResponses, ForgetResultErrors, ThrowOnError> => (options.client ?? client).delete<ForgetResultResponses, ForgetResultErrors, ThrowOnError>({ url: '/api/v1/evaluation-results/{evaluation_id}', ...options });

export const getResult = <ThrowOnError extends boolean = false>(options: Options<GetResultData, ThrowOnError>): RequestResult<GetResultResponses, GetResultErrors, ThrowOnError> => (options.client ?? client).get<GetResultResponses, GetResultErrors, ThrowOnError>({ url: '/api/v1/evaluation-results/{evaluation_id}', ...options });

